\begin{bgvisualreading}
All approximations agree at \(x=0\). The higher-degree polynomials bend with the sine curve longer before the omitted terms become noticeable.
\end{bgvisualreading}

\begin{bgconcept}[title={Taylor polynomial}]

The degree-\(n\) Taylor polynomial for \(f\) centered at \(a\) is
\[
P_n(x)=\sum_{k=0}^{n}\frac{f^{(k)}(a)}{k!}(x-a)^k.
\]

\end{bgconcept}

\begin{bgguided}[title={A cubic approximation for \(e^x\)}]

Every derivative of \(e^x\) equals \(e^x\), so at \(a=0\) each derivative value is \(1\). Thus
\[
P_3(x)=1+x+\frac{x^2}{2}+\frac{x^3}{6}.
\]
At zero, this polynomial matches \(e^x\) and its first three derivatives.

\end{bgguided}

\begin{bgexample}[title={Build a polynomial directly from derivative data}]
Suppose
\[
f(1)=2,\quad f'(1)=-3,\quad f''(1)=4,\quad f^{(3)}(1)=6.
\]
The degree-three Taylor polynomial centered at \(1\) is
\[
T_3(x)=2-3(x-1)+\frac{4}{2!}(x-1)^2+\frac{6}{3!}(x-1)^3.
\]
Thus
\[
T_3(x)=2-3(x-1)+2(x-1)^2+(x-1)^3.
\]
Each derivative condition can be checked by differentiating this polynomial.
\end{bgexample}

\begin{bgmistake}[title={Center the powers at a, not at zero unless a is zero}]
A Taylor polynomial about \(a\) uses \((x-a)^n\). Using \(x^n\) instead generally matches derivatives at the wrong point.
\end{bgmistake}

\begin{bgcheck}{u4b-taylor_polynomials-01}{expression}{1+x+x^2/2+x^3/6}[Quick check]

Find the cubic Maclaurin polynomial for \(e^x\).

\begin{bghint}

All derivatives at zero equal one.

\end{bghint}

\begin{bgreveal}

\[P_3(x)=1+x+\frac{x^2}{2}+\frac{x^3}{6}.\]

\end{bgreveal}

\end{bgcheck}

