\section{Maclaurin Series}

\lessonobjective{construct a Maclaurin series formally and distinguish a Taylor series from the function it may represent.}

\begin{bgexposition}[title={An infinite Taylor polynomial is a candidate representation}]

Letting the degree grow without bound produces the formal Maclaurin series \(\sum f^{(n)}(0)x^n/n!\). The series is built from the function, but it need not equal the function automatically. Equality requires the remainder to approach zero.



This distinction separates algebraic construction from analytic justification. Some smooth functions have all derivatives and still are not represented by their Taylor series away from the center. In ordinary calculus examples such as exponential and trigonometric functions, remainder estimates establish equality on large domains.

\end{bgexposition}

\begin{bgbridge}[title={A Maclaurin series records every derivative at zero}]
A Maclaurin series is a Taylor series centered at \(0\). Its coefficients form a derivative fingerprint:
\[
f(x)\sim \sum_{n=0}^{\infty}\frac{f^{(n)}(0)}{n!}x^n.
\]
For functions with repeating derivative patterns, this produces memorable series efficiently.

The symbol “equals” requires justification. Derivative matching constructs the formal candidate series, but the function equals that infinite series only where the Taylor remainder tends to zero. This distinction separates calculating coefficients from proving representation.
\end{bgbridge}

\begin{bgvisual}{u4b-derivative-cycle}{Derivative cycles generate coefficient patterns}{A four-step cycle shows cosine, negative sine, negative cosine, and sine, with their values at zero determining alternating even-power coefficients.}
\begin{tikzpicture}[node distance=1.2cm and 1.3cm,>=Stealth]
\node[draw,circle] (c) {$\cos x$};\node[draw,circle,right=of c] (ns) {$-\sin x$};
\node[draw,circle,below=of ns] (nc) {$-\cos x$};\node[draw,circle,left=of nc] (s) {$\sin x$};
\draw[->] (c)--(ns);\draw[->] (ns)--(nc);\draw[->] (nc)--(s);\draw[->] (s)--(c);
\node[below=.2cm of c] {$1$ at $0$};\node[below=.2cm of ns] {$0$ at $0$};\node[above=.2cm of nc] {$-1$ at $0$};\node[above=.2cm of s] {$0$ at $0$};
\end{tikzpicture}
\end{bgvisual}

\begin{bgproofidea}[title={Coefficient construction and function representation are separate theorems}]
The derivative data uniquely determine the Taylor coefficients. Taylor's Theorem later shows that
\[
f(x)=T_n(x)+R_n(x).
\]
Only when \(R_n(x)\to0\) does the infinite series actually equal \(f(x)\).
\end{bgproofidea}

\begin{bgconcept}[title={Maclaurin series}]

The Maclaurin series of \(f\) is
\[
\sum_{n=0}^{\infty}\frac{f^{(n)}(0)}{n!}x^n.
\]

\end{bgconcept}

\begin{bgguided}[title={The sine pattern}]

The derivatives of \(\sin x\) cycle:
\[
\sin x,\ \cos x,\ -\sin x,\ -\cos x,\ldots
\]
At zero the nonzero values occur at odd orders with alternating signs, giving
\[
\sin x=x-\frac{x^3}{3!}+\frac{x^5}{5!}-\cdots.
\]

\end{bgguided}

\begin{bgexample}[title={The cosine derivative cycle chooses the even powers}]
The derivatives of \(\cos x\) cycle:
\[
\cos x,-\sin x,-\cos x,\sin x,\ldots
\]
At \(x=0\), their values are \(1,0,-1,0,\ldots\). Therefore
\[
\cos x=1-\frac{x^2}{2!}+\frac{x^4}{4!}-\frac{x^6}{6!}+\cdots.
\]
Odd powers vanish because every odd derivative is zero at the center.
\end{bgexample}

\begin{bgmistake}[title={Derivative matching creates a candidate, not automatically an identity}]
A smooth function can have all derivatives at zero and still fail to equal its Taylor series away from zero. Equality requires a remainder argument.
\end{bgmistake}

\begin{bgcheck}{u4b-maclaurin_series-01}{expression}{x-x^3/6+x^5/120}[Quick check]

Write the first three nonzero Maclaurin terms of \(\sin x\).

\begin{bghint}

Use odd powers and alternating signs.

\end{bghint}

\begin{bgreveal}

\[x-\frac{x^3}{3!}+\frac{x^5}{5!}.\]

\end{bgreveal}

\end{bgcheck}

