\addplot[BGInk,very thick,domain=-1:3,samples=150]{exp(x/2)};\addlegendentry{$f(x)$}
\addplot[BGBlue,dashed,domain=-1:3]{1+x/2+x^2/8};\addlegendentry{center $0$}
\addplot[BGGold,dash dot,domain=-1:3]{exp(1/2)*(1+(x-1)/2+(x-1)^2/8)};\addlegendentry{center $1$}
\end{axis}
