\begin{bgconcept}[title={Taylor series}]

The Taylor series of \(f\) centered at \(a\) is
\[
\sum_{n=0}^{\infty}\frac{f^{(n)}(a)}{n!}(x-a)^n.
\]

\end{bgconcept}

\begin{bgguided}[title={Expand \(\ln x\) around \(1\)}]

For \(f(x)=\ln x\),
\[
f(1)=0,\quad f'(1)=1,\quad f''(1)=-1,\quad f^{(3)}(1)=2.
\]
Thus
\[
\ln x=(x-1)-\frac{(x-1)^2}{2}+\frac{(x-1)^3}{3}-\cdots,
\]
for the appropriate interval around \(1\).

\end{bgguided}

\begin{bgexample}[title={Approximate ln(1.1) from a center at 1}]
Let \(f(x)=\ln x\) and center at \(a=1\). Since
\[
f^{(n)}(1)=(-1)^{n-1}(n-1)!\quad(n\ge1),
\]
we obtain
\[
\ln x=(x-1)-\frac{(x-1)^2}{2}+\frac{(x-1)^3}{3}-\cdots.
\]
At \(x=1.1\), using three terms gives
\[
0.1-\frac{0.1^2}{2}+\frac{0.1^3}{3}=0.095333\ldots,
\]
close to the true value because \(x-1=0.1\) is small.
\end{bgexample}

\begin{bgmistake}[title={Keep the expansion variable visible}]
When centered at \(a\), write and manipulate powers of \(x-a\). Expanding them too early often hides the center and creates coefficient errors.
\end{bgmistake}

\begin{bgcheck}{u4b-taylor_series_centered_at_a-01}{expression}{1}[Quick check]

What is the center of a series written in powers of \((x-1)\)?

\begin{bghint}

The center makes the power factor zero.

\end{bghint}

\begin{bgreveal}

The center is \(a=1\).

\end{bgreveal}

\end{bgcheck}

