\node at (0,1) {$\sin x=x-\frac{x^3}{3!}+\frac{x^5}{5!}-\cdots$};
\node at (0,0) {$\cos x=1-\frac{x^2}{2!}+\frac{x^4}{4!}-\cdots$};
\draw[BGBlue,thick] (-.2,-.35) rectangle (7.9,2.45);
