\begin{bgconcept}[title={Standard library}]

\[
\frac1{1-x}=\sum_{n=0}^{\infty}x^n,\quad |x|<1,
\]
\[
e^x=\sum_{n=0}^{\infty}\frac{x^n}{n!},\quad
\sin x=\sum_{n=0}^{\infty}(-1)^n\frac{x^{2n+1}}{(2n+1)!},
\]
\[
\cos x=\sum_{n=0}^{\infty}(-1)^n\frac{x^{2n}}{(2n)!}.
\]

\end{bgconcept}

\begin{bgguided}[title={Approximate \(e^{0.1}\)}]

Using four terms,
\[
e^{0.1}\approx1+0.1+\frac{0.1^2}{2}+\frac{0.1^3}{6}=1.105166\ldots
\]
The next terms are already small because factorials grow rapidly.

\end{bgguided}

\begin{bgexample}[title={Substitute into a standard series without losing the pattern}]
From
\[
\sin u=u-\frac{u^3}{3!}+\frac{u^5}{5!}-\cdots,
\]
set \(u=2x\). Then
\[
\sin(2x)=2x-\frac{(2x)^3}{3!}+\frac{(2x)^5}{5!}-\cdots
=2x-\frac{4}{3}x^3+\frac{4}{15}x^5-\cdots.
\]
The powers remain odd and the signs still alternate. Because the sine series converges for every real input, the transformed series also converges for every real \(x\).
\end{bgexample}

\begin{bgmistake}[title={Transform the entire term, not only the first power}]
When replacing \(u\) by \(2x\), every occurrence becomes \((2x)^{2n+1}\). Writing \(2x^{2n+1}\) loses powers of two.
\end{bgmistake}

\begin{bgcheck}{u4b-standard_maclaurin_series-01}{expression}{1-x^2/2+x^4/24}[Quick check]

Write the first three nonzero Maclaurin terms of \(\cos x\).

\begin{bghint}

