\node[draw,rounded corners,right=of g] (d) {$\frac1{(1-u)^2}=\sum(n+1)u^n$};
\node[draw,rounded corners,right=of d] (s) {$u=x^2$\\$|x|<1$};
\node[draw,rounded corners,right=of s] (m) {multiply by $x$};
\draw[->] (g)--node[above]{differentiate}(d);\draw[->] (d)--(s);\draw[->] (s)--(m);
\end{tikzpicture}
