\begin{bgconcept}[title={Transformation rule of thumb}]

Start from a named series with its domain, perform one algebraic operation, rewrite the coefficient pattern, and translate the domain before simplifying.

\end{bgconcept}

\begin{bgguided}[title={Expand \(xe^{-x^2}\)}]

From
\[
e^u=\sum_{n=0}^{\infty}\frac{u^n}{n!},
\]
set \(u=-x^2\) and multiply by \(x\):
\[
xe^{-x^2}=\sum_{n=0}^{\infty}(-1)^n\frac{x^{2n+1}}{n!},
\]
valid for every real \(x\).

\end{bgguided}

\begin{bgexample}[title={Differentiate after a substitution}]
Find a power series for
\[
\frac{x}{(1-x^2)^2}.
\]
Start with
\[
\frac1{1-u}=\sum_{n=0}^{\infty}u^n.
\]
Differentiate with respect to \(u\):
\[
\frac1{(1-u)^2}=\sum_{n=0}^{\infty}(n+1)u^n.
\]
Set \(u=x^2\) and multiply by \(x\):
\[
\frac{x}{(1-x^2)^2}=\sum_{n=0}^{\infty}(n+1)x^{2n+1},
\qquad |x|<1.
\]
\end{bgexample}

\begin{bgmistake}[title={The order of operations matters}]
Differentiating with respect to \(x\) before or after substituting \(u=x^2\) produces different chain-rule factors. State which variable each derivative uses.
\end{bgmistake}

\begin{bgcheck}{u4b-building_new_series-01}{expression}{sum (-1)^n*x^(2n+1)/n!}[Quick check]

Find a series for \(xe^{-x^2}\).

\begin{bghint}

Substitute \(-x^2\) into the exponential series, then multiply by \(x\).

\end{bghint}

\begin{bgreveal}

\[xe^{-x^2}=\sum_{n=0}^{\infty}(-1)^n\frac{x^{2n+1}}{n!}.\]

\end{bgreveal}

\end{bgcheck}

