\addplot[BGBlue,dashed,domain=-.8:.8]{1+x/2};\addlegendentry{$T_1$}
\addplot[BGGold,dash dot,domain=-.8:.8]{1+x/2-x^2/8};\addlegendentry{$T_2$}
\addplot[BGGreen,thick,domain=-.8:.8]{1+x/2-x^2/8+x^3/16};\addlegendentry{$T_3$}
