\begin{bgproofidea}[title={The ratio test fixes the natural radius}]
For consecutive binomial terms, the magnitude ratio approaches \(|x|\). Thus the series converges absolutely for \(|x|<1\) and diverges for \(|x|>1\); endpoints require separate analysis depending on \(\alpha\).
\end{bgproofidea}

\begin{bgconcept}[title={Generalized binomial series}]

For \(|x|<1\),
\[
(1+x)^\alpha=\sum_{n=0}^{\infty}\binom{\alpha}{n}x^n,
\quad
\binom{\alpha}{n}=\frac{\alpha(\alpha-1)\cdots(\alpha-n+1)}{n!}.
\]

\end{bgconcept}

\begin{bgguided}[title={Square-root approximation}]

With \(\alpha=1/2\),
\[
\sqrt{1+x}=1+\frac12x-\frac18x^2+\frac1{16}x^3-\cdots.
\]
At \(x=0.04\), the quadratic approximation gives \(1.0198\), close to \(\sqrt{1.04}\).

\end{bgguided}

\begin{bgexample}[title={Expand a reciprocal square root}]
For \(\alpha=-1/2\),
\[
(1+x)^{-1/2}=1-\frac12x+\frac38x^2-\frac5{16}x^3+\cdots,
\qquad |x|<1.
\]
The coefficients come from
\[
\binom{-1/2}{2}=\frac{(-1/2)(-3/2)}{2!}=\frac38,
\]
and
\[
\binom{-1/2}{3}=\frac{(-1/2)(-3/2)(-5/2)}{3!}=-\frac5{16}.
\]
\end{bgexample}

\begin{bgmistake}[title={The generalized coefficient is a falling product}]
The numerator uses \(\alpha,\alpha-1,\alpha-2,\ldots\), not repeated powers of \(\alpha\).
\end{bgmistake}

