\section{Taylor's Theorem and the Remainder}

\lessonobjective{use Taylor's theorem to express approximation error and identify a derivative bound.}

\begin{bgexposition}[title={Approximation becomes mathematics only when error is controlled}]

A Taylor polynomial matches derivatives at the center, but matching alone does not say how far away the approximation remains accurate. Taylor's theorem represents the difference \(f(x)-P_n(x)\) using the next derivative evaluated at an unknown intermediate point. Bounding that derivative produces a usable error guarantee.



The unknown point \(c\) lies between the center and the target input. We do not need to find it; we need a bound \(M\) valid throughout that interval. Then factorial growth in the denominator often drives the error rapidly toward zero. The theorem is the bridge from formal Taylor coefficients to a proven representation.

\end{bgexposition}

\begin{bgbridge}[title={Approximation becomes mathematics when the error is bounded}]
A Taylor polynomial may look accurate on a graph, but a graph cannot certify digits. Taylor's Theorem expresses the exact error after degree \(n\) as
\[
R_n(x)=\frac{f^{(n+1)}(c)}{(n+1)!}(x-a)^{n+1}
\]
for some point \(c\) between \(a\) and \(x\).

We usually do not know \(c\). Instead, bound \(|f^{(n+1)}(t)|\le M\) throughout the interval and obtain
\[
|R_n(x)|\le \frac{M|x-a|^{n+1}}{(n+1)!}.
\]
The factorial in the denominator explains why many Taylor approximations improve rapidly near the center.
\end{bgbridge}

\begin{bgvisual}{u4b-taylor-error-envelope}{A Taylor polynomial comes with an error envelope}{A function and its Taylor polynomial meet at the center, while symmetric upper and lower error bounds widen with distance from the center.}
\begin{tikzpicture}
\begin{axis}[width=.82\textwidth,height=.4\textwidth,xmin=-1.5,xmax=1.5,ymin=-1.3,ymax=1.3,grid=major,legend pos=south east]
\addplot[BGInk,very thick,domain=-1.5:1.5,samples=150]{sin(deg(x))};\addlegendentry{$\sin x$}
\addplot[BGBlue,thick,domain=-1.5:1.5]{x-x^3/6};\addlegendentry{$T_3$}
\addplot[BGGold,dashed,domain=-1.5:1.5]{x-x^3/6+abs(x)^4/24};
\addplot[BGGold,dashed,domain=-1.5:1.5]{x-x^3/6-abs(x)^4/24};\addlegendentry{error envelope}
\end{axis}
\end{tikzpicture}
\end{bgvisual}

\begin{bgdecision}[title={Taylor error-bound checklist}]
Identify the center \(a\), degree \(n\), and target \(x\). Find a bound \(M\) for \(|f^{(n+1)}(t)|\) on the entire interval between \(a\) and \(x\). Substitute into the Lagrange bound, preserve enough precision until the end, and compare the result with the requested tolerance.
\end{bgdecision}
\begin{bgproofidea}[title={The remainder theorem is a high-order Mean Value Theorem}]
The proof constructs an auxiliary function whose zeros force repeated applications of Rolle's Theorem. The resulting point \(c\) converts unmatched higher-order behavior into the exact remainder formula. The full proof is longer, but the mechanism is the same idea that converts average change into a derivative value somewhere inside an interval.
\end{bgproofidea}

\begin{bgvisual}{u4b-remainder-band}{A remainder bound encloses the unknown error}{Taylor's theorem does not merely offer a polynomial; it gives an explicit envelope within which the true function must lie.}
\begin{tikzpicture}
\begin{axis}[width=.78\textwidth,height=.42\textwidth,xmin=-1.2,xmax=1.2,ymin=.2,ymax=3.5,axis lines=middle,xlabel={$x$},ylabel={$y$},grid=major,major grid style={draw=BGLine},samples=200]
\addplot[name path=upper,draw=none,domain=-1.2:1.2]{1+x+x^2/2+abs(x)^3};
\addplot[name path=lower,draw=none,domain=-1.2:1.2]{1+x+x^2/2-abs(x)^3};
\addplot[BGGold!25] fill between[of=upper and lower];
\addplot[BGInk,very thick,domain=-1.2:1.2]{exp(x)};
\addplot[BGBlue,dashed,thick,domain=-1.2:1.2]{1+x+x^2/2};
\end{axis}
\end{tikzpicture}
\end{bgvisual}
\begin{bgvisualreading}
The dashed polynomial is the approximation. The shaded band represents a deliberately simple error allowance, and the true exponential curve stays inside it on the displayed interval.
\end{bgvisualreading}

\begin{bgconcept}[title={Lagrange remainder}]

For some \(c\) between \(a\) and \(x\),
\[
R_n(x)=f(x)-P_n(x)=\frac{f^{(n+1)}(c)}{(n+1)!}(x-a)^{n+1}.
\]
Hence if \(|f^{(n+1)}(t)|\le M\), then
\[
|R_n(x)|\le\frac{M|x-a|^{n+1}}{(n+1)!}.
\]

\end{bgconcept}

\begin{bgguided}[title={Bound exponential error}]

Approximate \(e^{0.5}\) with \(P_3\). On \([0,0.5]\), the fourth derivative is \(e^t\le e^{0.5}\). Therefore
\[
|R_3(0.5)|\le\frac{e^{0.5}(0.5)^4}{4!}<0.0043.
\]

\end{bgguided}

\begin{bgexample}[title={Certify a sine approximation}]
Approximate \(\sin(0.2)\) by \(T_3(x)=x-x^3/6\). The next derivative after degree three is \(\sin x\), whose absolute value is at most \(1\). Therefore
\[
|R_3(0.2)|\le\frac{0.2^4}{4!}
=\frac{0.0016}{24}<0.000067.
\]
Thus the cubic approximation is guaranteed accurate to within about \(6.7\times10^{-5}\).
\end{bgexample}

\begin{bgmistake}[title={M must bound the derivative on the entire interval}]
Using only \(|f^{(n+1)}(a)|\) is not generally enough. The bound must hold between the center and the target input.
\end{bgmistake}

\begin{bgcheck}{u4b-taylor_remainder_theorem-01}{expression}{M*|x-a|^(n+1)/(n+1)!}[Quick check]

State the standard Lagrange upper bound for \(|R_n(x)|\).

\begin{bghint}

Use a bound \(M\) on the \((n+1)\)st derivative.

\end{bghint}

\begin{bgreveal}

\[|R_n(x)|\le\frac{M|x-a|^{n+1}}{(n+1)!}.\]

\end{bgreveal}

\end{bgcheck}

