\section{Using Series to Approximate Definite Integrals}

\lessonobjective{integrate a power series to approximate a definite integral lacking an elementary antiderivative.}

\begin{bgexposition}[title={Power series can replace an unavailable antiderivative}]

Some important integrals cannot be expressed with elementary functions. A power series for the integrand can still be integrated term by term, producing a rapidly computable numerical approximation. The method is especially effective on a small interval where powers shrink quickly.



The approximation must include an error argument. This may come from alternating-series error, a remainder bound for the integrand series, or a bound on the integrated tail. The method is not numerical guesswork; it is exact symbolic transformation followed by controlled truncation.

\end{bgexposition}

\begin{bgbridge}[title={Integrate the polynomial approximation when no elementary antiderivative exists}]
Some important functions, such as \(e^{-x^2}\), have no elementary antiderivative. A power series turns the integrand into an infinite polynomial, which can be integrated term by term on a suitable interval.

The method has three distinct stages: expand the integrand, integrate the series, and control the truncation error. The result is not merely a numerical trick; it creates a convergent representation of a genuinely new function.
\end{bgbridge}

\begin{bgvisual}{u4b-gaussian-series-integral}{Polynomial approximations make a nonelementary integral computable}{The curve e to the negative x squared is compared with two truncated series on the interval from zero to one half, with the area under each shown.}
\begin{tikzpicture}
\begin{axis}[width=.82\textwidth,height=.4\textwidth,xmin=0,xmax=.7,ymin=.55,ymax=1.05,grid=major,legend pos=south west]
\addplot[BGInk,very thick,domain=0:.7,samples=150]{exp(-x^2)};\addlegendentry{$e^{-x^2}$}
\addplot[BGBlue,dashed,domain=0:.7]{1-x^2};\addlegendentry{$1-x^2$}
\addplot[BGGreen,thick,domain=0:.7]{1-x^2+x^4/2};\addlegendentry{$1-x^2+x^4/2$}
\end{axis}
\end{tikzpicture}
\end{bgvisual}

\begin{bgconcept}[title={Integrate the series, not the impossible antiderivative}]

If \(f(x)=\sum c_nx^n\) on the interval of integration, then
\[
\int_0^b f(x)\,dx=\sum_{n=0}^{\infty}\frac{c_n b^{n+1}}{n+1},
\]
provided termwise integration is justified.

\end{bgconcept}

\begin{bgguided}[title={Approximate a Gaussian-type integral}]

Since
\[
e^{-x^2}=1-x^2+\frac{x^4}{2!}-\frac{x^6}{3!}+\cdots,
\]
we obtain
\[
\int_0^{0.5}e^{-x^2}\,dx
=0.5-\frac{0.5^3}{3}+\frac{0.5^5}{10}-\frac{0.5^7}{42}+\cdots.
\]
The series alternates with rapidly shrinking terms.

\end{bgguided}

\begin{bgexample}[title={Approximate a Gaussian integral on a short interval}]
Since
\[
e^{-x^2}=1-x^2+\frac{x^4}{2!}-\frac{x^6}{3!}+\cdots,
\]
we have
\[
\int_0^{1/2}e^{-x^2}\,dx
=\left[x-\frac{x^3}{3}+\frac{x^5}{10}-\frac{x^7}{42}+\cdots\right]_0^{1/2}.
\]
Using the first three integrated terms gives
\[
\frac12-\frac{1}{24}+\frac{1}{320}=0.461458\ldots.
\]
The next integrated term has magnitude \(1/(42\cdot2^7)<0.000187\), which supplies an alternating error bound.
\end{bgexample}

\begin{bgmistake}[title={Integrate the coefficients as well as the powers}]
The term \(c_nx^n\) integrates to \(c_nx^{n+1}/(n+1)\). Forgetting the new denominator changes every approximation after the first term.
\end{bgmistake}

\begin{bgcheck}{u4b-series_for_definite_integrals-01}{expression}{0.5-0.5^3/3+0.5^5/10}[Quick check]

Use three terms to approximate \(\int_0^{0.5}e^{-x^2}\,dx\).

\begin{bghint}

