\section{Small-Angle Approximations in Physics}

\lessonobjective{use Taylor polynomials to justify common small-angle approximations and estimate their errors.}

\begin{bgexposition}[title={Physical models often simplify because a variable is small}]

Near zero, \(\sin\theta\approx\theta\) and \(\cos\theta\approx1-\theta^2/2\) when angles are measured in radians. These are not arbitrary engineering tricks. They are low-degree Maclaurin polynomials whose errors can be bounded.



The approximations linearize otherwise nonlinear models. A pendulum equation involving \(\sin\theta\) becomes a linear differential equation when angular displacement is small. Optics, wave motion, and rotational mechanics use similar simplifications. The phrase ``small angle'' must be tied to a tolerance, not merely intuition.

\end{bgexposition}

\begin{bgbridge}[title={A local approximation can simplify a physical law}]
For angles near zero measured in radians,
\[
\sin\theta=\theta-\frac{\theta^3}{6}+\cdots,
\]
so \(\sin\theta\approx\theta\). This replacement turns nonlinear equations into linear ones and explains why many small-oscillation systems behave approximately like simple harmonic motion.

The approximation has a domain of usefulness, not universal authority. The cubic correction estimates the error and shows how accuracy deteriorates as the angle grows. Units matter: the derivative-based series is built for radians, so degree input destroys the approximation scale.
\end{bgbridge}

\begin{bgvisual}{u4b-small-angle-comparison}{Sine and angle agree locally but separate farther away}{The curves y equals sine theta and y equals theta nearly overlap near zero, while a magnified error panel shows their cubic separation.}
\begin{tikzpicture}
\begin{axis}[width=.82\textwidth,height=.4\textwidth,xmin=-1.2,xmax=1.2,ymin=-1.2,ymax=1.2,grid=major,legend pos=north west,xlabel={$\theta$}]
\addplot[BGInk,very thick,domain=-1.2:1.2,samples=150]{sin(deg(x))};\addlegendentry{$\sin\theta$}
\addplot[BGGold,dashed,domain=-1.2:1.2]{x};\addlegendentry{$\theta$}
\end{axis}
\end{tikzpicture}
\end{bgvisual}

\begin{bgconcept}[title={Two standard approximations}]

For small \(|\theta|\),
\[
\sin\theta=\theta+O(\theta^3),\qquad
\cos\theta=1-\frac{\theta^2}{2}+O(\theta^4).
\]

\end{bgconcept}

\begin{bgguided}[title={Quantify the sine approximation}]

At \(\theta=0.1\),
\[
|\sin\theta-\theta|\le\frac{0.1^3}{3!}\approx1.67\times10^{-4}.
\]
Thus the linear approximation is accurate to better than two ten-thousandths.

\end{bgguided}

\begin{bgexample}[title={Estimate the pendulum-model error at ten degrees}]
Ten degrees is \(\theta=\pi/18\approx0.1745\) radians. The leading difference between \(\theta\) and \(\sin\theta\) is approximately
\[
\frac{\theta^3}{6}\approx\frac{(0.1745)^3}{6}\approx0.000886.
\]
Relative to \(\theta\), this is about \(0.51\%\). Thus the small-angle replacement is quite accurate at ten degrees, while the calculation also quantifies what “small” means.
\end{bgexample}

\begin{bgmistake}[title={Small-angle formulas require radians}]
The approximation \(\sin\theta\approx\theta\) compares dimensionless radian measure with sine. Substituting degrees directly can produce nonsense.
\end{bgmistake}

