\addplot[BGBlue,domain=0:1,samples=150]{x^2};\addlegendentry{$x^2$}
\addplot[BGGold,domain=0:1,samples=150]{x^6};\addlegendentry{$x^6$}
\addplot[BGGreen,domain=0:1,samples=150]{x^20};\addlegendentry{$x^{20}$}
\end{axis}
\end{tikzpicture}
\end{bgvisual}

\begin{bgadvanced}[title={What is required now and what belongs to analysis}]
For Calculus II, the essential distinction is operational: pointwise convergence may use a different cutoff at each input, while uniform convergence supplies one cutoff for the entire set. A later analysis course proves the theorems that let uniform limits preserve continuity and interact safely with integrals. Here, the goal is to recognize why power series are well controlled on closed intervals strictly inside their radius.
\end{bgadvanced}
\begin{bgdefinition}[title={Uniform convergence}]
A sequence \(f_n\) converges uniformly to \(f\) on a set \(E\) if
\[
\forall\varepsilon>0\;\exists N\;\forall n\ge N\;\forall x\in E,
\qquad |f_n(x)-f(x)|<\varepsilon.
\]
The same \(N\) must work for every \(x\in E\).
\end{bgdefinition}
\begin{bgproofidea}[title={Power series gain uniform control away from the boundary}]
On \(|x-a|\le r<R\), choose \(\rho\) with \(r<\rho<R\). Coefficients are controlled at distance \(\rho\), leaving a geometric factor \((r/\rho)^n\). This common bound works for all \(x\) in the smaller interval.
\end{bgproofidea}

\begin{bgconcept}[title={Uniform convergence in working language}]

Uniform convergence means that one sufficiently large index works simultaneously for every point in the domain, rather than choosing a different index for each point.

\end{bgconcept}

\begin{bgguided}[title={A geometric tail controls all points in a smaller interval}]

If \(|x|\le r<R\), coefficient estimates for a power series produce a common geometric bound involving \((r/R)^n\). Because that bound is independent of the particular \(x\), the entire tail is controlled at once.

\end{bgguided}

\begin{bgexample}[title={Pointwise convergence without uniform convergence}]
On \([0,1)\), let \(f_n(x)=x^n\). For every fixed \(x<1\), \(x^n\to0\). But
\[
\sup_{0\le x<1}|x^n-0|=1
\]
for every \(n\), because values of \(x\) can be chosen arbitrarily close to \(1\). The maximum error never becomes uniformly small, so convergence is not uniform.
\end{bgexample}

\begin{bgmistake}[title={Do not let the uniform cutoff depend on x}]
In uniform convergence, \(N\) may depend on \(\varepsilon\) but not on the point \(x\). Allowing \(N=N(x,\varepsilon)\) gives only pointwise convergence.
\end{bgmistake}

\begin{bgcheck}{u4b-uniform_convergence_preview-01}{multiple_choice}{uniform}[Quick check]

